sumber:
DECLARE @Name VARCHAR(50);
SET @Name = 'Deepak';
SELECT
CASE @Name
WHEN 'Deepak' THEN 'Hello Deepak!'
WHEN 'Manoj' THEN 'Hello Manoj!'
ELSE 'Siapa kamu?'
END AS Pesan;

